<script setup lang="ts">definePageMeta({layout:"default"});useSeoMeta({title:"عملیات بررسی محتوا | هفت‌سو",robots:"noindex,nofollow"});const{action,items,load,message,metrics,pending,selected}=useContentOperations(),state=ref("all");onMounted(()=>load());watch(state,(value:string)=>load(value));</script>
<template><main id="main-content" class="operations-admin content-container"><header class="operations-header"><div><p class="eyebrow">مرکز عملیات اعتماد</p><h1>گزارش‌ها و SLA بررسی محتوا</h1><p>صف زنده، تخصیص ایمن پرونده، تشدید و سنجش کیفیت تصمیم کارکنان.</p></div><label>نمای صف<select v-model="state"><option value="all">همه پرونده‌ها</option><option value="open">آزاد</option><option value="claimed">تخصیص‌یافته</option><option value="escalated">تشدیدشده</option></select></label></header><OperationsMetrics :metrics="metrics"/><UiState v-if="pending" kind="loading" title="در حال دریافت عملیات" description="SLA و اولویت پرونده‌ها محاسبه می‌شود."/><UiState v-else-if="!items.length" kind="empty" title="پرونده‌ای در این صف نیست" description="فیلتر دیگری انتخاب کنید."/><div v-else class="operations-workspace"><OperationsQueue :items="items" :active-id="selected?.id" @select="selected=$event"/><OperationsCaseWorkspace v-if="selected" :item="selected" @action="action"/></div><p v-if="message" class="post-action-message" role="status">{{message}}</p></main></template>

